style.css:
@-moz-document domain("roblox.com") {
/* 1. HIDE EVERYTHING IN THE LOGO AREA */
    .rbx-header .icon-logo, 
    .rbx-header .icon-logo-r,
    .navbar-brand {
        opacity: 0 !important;
    }

    /* 2. FORCE NICKI INTO THE VOID */
    .rbx-header::after {
        content: "" !important;
        position: absolute !important;
        top: 2px !important;
        left: 10px !important;
        width: 130px !important; 
        height: 40px !important;
        
        /* NEW DIRECT LINK METHOD */
        background: url("https://i.giphy.com/media/v1.Y2lkPTc5MGI3NjExNHJmZzBqZzZqZzZqZzZqZzZqZzZqZzZqZzZqZzZqZzZqZzZqJm09ZlsZSZkPTE/WaUjcbdF_o/giphy.gif") no-repeat center !important;
        background-size: contain !important;
        
        z-index: 99999 !important;
        display: block !important;
        visibility: visible !important;
    }

    /* 3. KEEP THE PINK BAR */
    .rbx-header {
        background-color: #FFB7D5 !important;
    }
}
